// ─── Typewriter hook ──────────────────────────────────────────────────────────
function useTypewriter(lines, typingSpeed = 75, pauseMs = 1600, deleteSpeed = 35) {
  const [displayed, setDisplayed] = useState('')
  const [lineIdx, setLineIdx] = useState(0)
  const [phase, setPhase] = useState('typing')

  useEffect(() => {
    const line = lines[lineIdx].text
    let timer
    if (phase === 'typing') {
      if (displayed.length < line.length) {
        timer = setTimeout(() => setDisplayed(line.slice(0, displayed.length + 1)), typingSpeed)
      } else {
        timer = setTimeout(() => setPhase('pausing'), pauseMs)
      }
    } else if (phase === 'pausing') {
      timer = setTimeout(() => setPhase('deleting'), 200)
    } else {
      if (displayed.length > 0) {
        timer = setTimeout(() => setDisplayed(displayed.slice(0, -1)), deleteSpeed)
      } else {
        setLineIdx((lineIdx + 1) % lines.length)
        setPhase('typing')
      }
    }
    return () => clearTimeout(timer)
  }, [displayed, phase, lineIdx]) // eslint-disable-line

  return { displayed, lineIdx }
}

// ─── Marquee strip ────────────────────────────────────────────────────────────
const MARQUEE_ITEMS = ['AI EXPERT', '•', 'AUTOMATION', '•', 'WEBSITES', '•', 'CHATBOTS', '•', 'CUSTOM SOFTWARE', '•', 'PYTHON', '•']

function SlidingStrip() {
  return (
    <div style={{ overflow: 'hidden', width: '100%' }}>
      <style>{`
        @keyframes marquee { from { transform: translateX(0) } to { transform: translateX(-50%) } }
        .marquee-inner { animation: marquee 18s linear infinite; }
      `}</style>
      <div className="marquee-inner" style={{ display: 'flex', gap: '2rem', whiteSpace: 'nowrap', width: 'max-content', fontSize: 10, letterSpacing: '0.18em', color: 'rgba(255,255,255,0.28)', fontFamily: 'monospace', fontWeight: 500 }}>
        {[...MARQUEE_ITEMS, ...MARQUEE_ITEMS].map((item, i) => (
          <span key={i} style={{ color: item === '•' ? '#e63946' : undefined }}>{item}</span>
        ))}
      </div>
    </div>
  )
}

// ─── Wheel + photo — exact same structure as wheel_demo.html ─────────────────
function PhotoWheel() {
  return (
    <div style={{ width: 340, height: 340, position: 'relative', flexShrink: 0 }}>

      <style>{`
        @keyframes wheelSpin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        .wheel-spin { animation: wheelSpin 22s linear infinite; }
      `}</style>

      {/* 1 — SPINNING SVG ring (lowest, spins) */}
      <svg
        className="wheel-spin"
        viewBox="0 0 340 340"
        style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', zIndex: 1 }}
      >
        <defs>
          <path id="cp" d="M170,170 m-128,0 a128,128 0 1,1 256,0 a128,128 0 1,1 -256,0" />
        </defs>
        <circle cx="170" cy="170" r="160" fill="none" stroke="rgba(255,255,255,0.04)" strokeWidth="1" />
        <circle cx="170" cy="170" r="152" fill="none" stroke="rgba(255,255,255,0.07)" strokeWidth="0.6" />
        {Array.from({ length: 48 }, (_, i) => {
          const rad = (i / 48) * Math.PI * 2
          const inner = i % 4 === 0 ? 138 : 143
          return (
            <line key={i}
              x1={170 + inner * Math.cos(rad)} y1={170 + inner * Math.sin(rad)}
              x2={170 + 152 * Math.cos(rad)} y2={170 + 152 * Math.sin(rad)}
              stroke={i % 4 === 0 ? 'rgba(230,57,70,0.78)' : 'rgba(255,255,255,0.14)'}
              strokeWidth={i % 4 === 0 ? 1.6 : 0.7}
            />
          )
        })}
        {[0, 45, 90, 135, 180, 225, 270, 315].map(a => {
          const r = (a * Math.PI) / 180
          return <circle key={a} cx={170 + 152 * Math.cos(r)} cy={170 + 152 * Math.sin(r)} r="3.5" fill="#e63946" />
        })}
        <text fontSize="10.5" fill="rgba(255,255,255,0.42)" letterSpacing="4.2" fontFamily="monospace" fontWeight="500">
          <textPath href="#cp">AI EXPERT • AUTOMATION • WEBSITES • CHATBOTS • SOFTWARE •</textPath>
        </text>
      </svg>

      {/* 2 — STATIC red border ring (middle, never spins — acts as frame around photo) */}
      <svg
        viewBox="0 0 340 340"
        style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', zIndex: 2, pointerEvents: 'none' }}
      >
        <circle cx="170" cy="170" r="120" fill="none" stroke="rgba(230,57,70,0.60)" strokeWidth="2" />
      </svg>

      {/* 3 — PHOTO clipped to circle (top layer, inside the red ring) */}
      <div style={{
        position: 'absolute',
        top: '50%', left: '50%',
        transform: 'translate(-50%, -50%)',
        width: 236, height: 236,
        borderRadius: '50%',
        overflow: 'hidden',
        zIndex: 3,
      }}>
        <img
          src={PHOTO_SRC}
          alt="Surinder Kumar"
          style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'center top', display: 'block' }}
        />
      </div>

    </div>
  )
}

